import { Icon, type IconName } from "@/registry/p1/internal/icons";
import "./footer.css";

export interface FooterColumn {
  title: string;
  links: string;
}
export interface FooterProps {
  logo: string;
  tagline: string;
  columns: FooterColumn[];
  newsletter: "on" | "off";
  newsletterTitle: string;
  newsletterButton: string;
  social: "on" | "off";
  legal: "on" | "off";
  copyright: string;
  legalLinks: string;
  tone: "dark" | "accent" | "light";
}

const splitLines = (s: string) =>
  String(s || "")
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);

const SOCIAL_ICONS: IconName[] = ["globe", "mail", "external"];

export function FooterRender({
  logo,
  tagline,
  columns,
  newsletter,
  newsletterTitle,
  newsletterButton,
  social,
  legal,
  copyright,
  legalLinks,
  tone,
}: FooterProps) {
  const cols = columns || [];

  const socialRow = (
    <div className="p1-footer__social">
      {SOCIAL_ICONS.map((nm, i) => (
        <span key={i} className="p1-footer__social-btn">
          <Icon name={nm} className="p1-footer__social-icon" />
        </span>
      ))}
    </div>
  );

  return (
    <footer className="p1-footer" data-tone={tone}>
      <div className="p1-footer__inner">
        {newsletter === "on" && (
          <div className="p1-footer__newsletter">
            <div className="p1-footer__newsletter-title">{newsletterTitle}</div>
            <div className="p1-footer__newsletter-form">
              <span className="p1-footer__newsletter-field">you@company.com</span>
              <span className="p1-footer__newsletter-btn">
                {newsletterButton}
                <Icon name="arrow-right" className="p1-footer__newsletter-arrow" />
              </span>
            </div>
          </div>
        )}

        <div className="p1-footer__grid">
          <div className="p1-footer__brand">
            <div className="p1-footer__logo">{logo}</div>
            <p className="p1-footer__tagline">{tagline}</p>
          </div>
          {cols.map((c, i) => (
            <div key={i} className="p1-footer__col">
              <h5 className="p1-footer__col-head">{c.title}</h5>
              <ul className="p1-footer__col-list">
                {splitLines(c.links).map((ln, j) => (
                  <li key={j} className="p1-footer__col-item">
                    {ln}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>

        {legal === "on" && (
          <div className="p1-footer__legal">
            <span className="p1-footer__copyright">{copyright}</span>
            <div className="p1-footer__legal-links">
              {splitLines(legalLinks).map((ln, i) => (
                <span key={i} className="p1-footer__legal-item">
                  {ln}
                </span>
              ))}
            </div>
            <span className="p1-footer__legal-spacer" />
            {social === "on" && socialRow}
          </div>
        )}

        {legal !== "on" && social === "on" && (
          <div className="p1-footer__social-standalone">{socialRow}</div>
        )}
      </div>
    </footer>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { FooterRender, type FooterProps, type FooterColumn } from "./footer";
export type { FooterProps, FooterColumn };

export const FooterBlock: ComponentConfig<FooterProps> = {
  fields: {
    logo: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Brand name shown in the footer." },
    },
    tagline: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "1–2 sentence brand description below the logo." },
    },
    columns: {
      type: "array",
      arrayFields: {
        title: {
          type: "text" as const,
          contentEditable: true,
          visible: false,
          ai: { instructions: "Column heading. 1–2 words." },
        },
        links: { type: "textarea" },
      },
      defaultItemProps: { title: "Column", links: "Link one\nLink two" },
      getItemSummary: (item: FooterColumn) => item.title || "Column",
    },
    newsletter: {
      type: "radio" as const,
      options: [
        { label: "On", value: "on" },
        { label: "Off", value: "off" },
      ],
    },
    newsletterTitle: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Newsletter section heading. Under 6 words." },
    },
    newsletterButton: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Newsletter CTA label. 1–2 words." },
    },
    social: {
      type: "radio" as const,
      options: [
        { label: "On", value: "on" },
        { label: "Off", value: "off" },
      ],
    },
    legal: {
      type: "radio" as const,
      options: [
        { label: "On", value: "on" },
        { label: "Off", value: "off" },
      ],
    },
    copyright: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Copyright line. E.g. © 2026 Company, Inc." },
    },
    legalLinks: {
      type: "text" as const,
      ai: { instructions: "Legal link labels separated by newlines. E.g. Privacy\nTerms\nSecurity." },
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "Dark", value: "dark" },
        { label: "Accent", value: "accent" },
        { label: "Light", value: "light" },
      ],
    },
  },
  defaultProps: {
    logo: "Pantheon",
    tagline: "The WebOps platform for WordPress and Drupal. Build, launch, and run ambitious sites — together.",
    columns: [
      { title: "Product", links: "Overview\nIntegrations\nPricing\nChangelog" },
      { title: "Solutions", links: "Agencies\nEnterprise\nHigher ed\nGovernment" },
      { title: "Resources", links: "Docs\nGuides\nBlog\nSupport" },
      { title: "Company", links: "About\nCareers\nPartners\nContact" },
    ],
    newsletter: "on",
    newsletterTitle: "Ship better, every week.",
    newsletterButton: "Subscribe",
    social: "on",
    legal: "on",
    copyright: "© 2026 Pantheon Systems, Inc.",
    legalLinks: "Privacy\nTerms\nSecurity\nStatus",
    tone: "dark",
  },
  render: FooterRender,
};

export const meta = defineMeta({
  title: 'Footer',
  description: 'Site footer with logo, tagline, multi-column link groups, newsletter signup, social icons, and legal/copyright row in dark/indigo/light tones.',
  categories: ["global"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-footer {
  padding-block-end: var(--p1-space-lg);
  padding-block-start: var(--p1-space-xl);
  padding-inline: var(--p1-space-lg);
}

.p1-footer[data-tone="dark"] { background-color: var(--p1-surface-dark); }
.p1-footer[data-tone="accent"] { background-color: var(--p1-accent); }
.p1-footer[data-tone="light"] { background-color: var(--p1-surface-subtle); }

.p1-footer__inner { margin-inline: auto; max-inline-size: var(--p1-container-wide); }

/* Newsletter */
.p1-footer__newsletter {
  align-items: center;
  border-block-end: 1px solid;
  display: flex;
  flex-wrap: wrap;
  gap: var(--p1-space-lg);
  justify-content: space-between;
  margin-block-end: var(--p1-space-xl);
  padding-block-end: var(--p1-space-lg);
}
.p1-footer[data-tone="dark"] .p1-footer__newsletter { border-color: var(--p1-border-inverse); }
.p1-footer[data-tone="accent"] .p1-footer__newsletter { border-color: var(--p1-border-inverse); }
.p1-footer[data-tone="light"] .p1-footer__newsletter { border-color: var(--p1-border); }

.p1-footer__newsletter-title {
  font-size: var(--p1-text-2xl);
  font-weight: var(--p1-weight-bold);
  letter-spacing: -0.02em;
  max-inline-size: 28rem;
}
@media (width >= 48rem) {
  .p1-footer__newsletter-title { font-size: var(--p1-text-3xl); }
}
.p1-footer[data-tone="dark"] .p1-footer__newsletter-title,
.p1-footer[data-tone="accent"] .p1-footer__newsletter-title { color: var(--p1-fg-inverse); }
.p1-footer[data-tone="light"] .p1-footer__newsletter-title { color: var(--p1-fg-default); }

.p1-footer__newsletter-form {
  align-items: center;
  display: flex;
  flex: 1;
  gap: 0.625rem;
  justify-content: end;
  max-inline-size: 28rem;
}

.p1-footer__newsletter-field {
  border-radius: var(--p1-radius-card);
  border: 1px solid;
  flex: 1;
  font-size: var(--p1-text-sm);
  padding: 0.75rem 1rem;
}
.p1-footer[data-tone="dark"] .p1-footer__newsletter-field {
  background-color: var(--p1-input-inverse-bg);
  border-color: var(--p1-border-inverse);
  color: var(--p1-fg-inverse-muted);
}
.p1-footer[data-tone="accent"] .p1-footer__newsletter-field {
  background-color: var(--p1-input-inverse-bg);
  border-color: var(--p1-border-inverse-strong);
  color: var(--p1-fg-inverse-muted);
}
.p1-footer[data-tone="light"] .p1-footer__newsletter-field {
  background-color: var(--p1-surface-default);
  border-color: var(--p1-border);
  color: var(--p1-fg-muted);
}

.p1-footer__newsletter-btn {
  align-items: center;
  background-color: var(--p1-warning);
  border-radius: var(--p1-radius-pill);
  color: var(--p1-fg-default);
  display: inline-flex;
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  gap: 0.375rem;
  padding: 0.75rem 1.25rem;
  white-space: nowrap;
}

.p1-footer__newsletter-arrow { block-size: 1rem; inline-size: 1rem; }

/* Columns grid */
.p1-footer__grid {
  display: grid;
  gap: var(--p1-space-lg);
  grid-template-columns: repeat(2, 1fr);
}
@media (width >= 48rem) { .p1-footer__grid { grid-template-columns: repeat(3, 1fr); } }
@media (width >= 64rem) { .p1-footer__grid { grid-template-columns: 2fr repeat(4, 1fr); } }

.p1-footer__brand { grid-column: 1 / -1; }
@media (width >= 48rem) { .p1-footer__brand { grid-column: span 3; } }
@media (width >= 64rem) { .p1-footer__brand { grid-column: span 2; } }

.p1-footer__logo {
  font-size: var(--p1-text-xl);
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-block-end: var(--p1-space-sm);
}
.p1-footer[data-tone="dark"] .p1-footer__logo,
.p1-footer[data-tone="accent"] .p1-footer__logo { color: var(--p1-fg-inverse); }
.p1-footer[data-tone="light"] .p1-footer__logo { color: var(--p1-fg-default); }

.p1-footer__tagline {
  font-size: var(--p1-text-sm);
  line-height: var(--p1-leading-relaxed);
  margin: 0;
  max-inline-size: 20rem;
  text-wrap: pretty;
}
.p1-footer[data-tone="dark"] .p1-footer__tagline { color: var(--p1-fg-inverse-muted); }
.p1-footer[data-tone="accent"] .p1-footer__tagline { color: var(--p1-fg-inverse-muted); }
.p1-footer[data-tone="light"] .p1-footer__tagline { color: var(--p1-fg-muted); }

.p1-footer__col-head {
  font-size: var(--p1-text-xs);
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.06em;
  margin-block-end: var(--p1-space-md);
  text-transform: uppercase;
}
.p1-footer[data-tone="dark"] .p1-footer__col-head,
.p1-footer[data-tone="accent"] .p1-footer__col-head { color: var(--p1-fg-inverse); }
.p1-footer[data-tone="light"] .p1-footer__col-head { color: var(--p1-fg-default); }

.p1-footer__col-list { display: flex; flex-direction: column; gap: 0.625rem; list-style: none; margin: 0; padding: 0; }

.p1-footer__col-item { font-size: var(--p1-text-sm); }
.p1-footer[data-tone="dark"] .p1-footer__col-item { color: var(--p1-fg-inverse-muted); }
.p1-footer[data-tone="accent"] .p1-footer__col-item { color: var(--p1-fg-inverse-muted); }
.p1-footer[data-tone="light"] .p1-footer__col-item { color: var(--p1-fg-muted); }

/* Legal row */
.p1-footer__legal {
  align-items: center;
  border-block-start: 1px solid;
  display: flex;
  flex-direction: column;
  flex-wrap: wrap;
  gap: var(--p1-space-md);
  margin-block-start: var(--p1-space-xl);
  padding-block-start: var(--p1-space-md);
}
@media (width >= 40rem) {
  .p1-footer__legal { flex-direction: row; }
}
.p1-footer[data-tone="dark"] .p1-footer__legal { border-color: var(--p1-border-inverse); }
.p1-footer[data-tone="accent"] .p1-footer__legal { border-color: var(--p1-border-inverse); }
.p1-footer[data-tone="light"] .p1-footer__legal { border-color: var(--p1-border); }

.p1-footer__copyright,
.p1-footer__legal-item { font-size: var(--p1-text-xs); }
.p1-footer[data-tone="dark"] .p1-footer__copyright,
.p1-footer[data-tone="dark"] .p1-footer__legal-item { color: var(--p1-fg-inverse-muted); }
.p1-footer[data-tone="accent"] .p1-footer__copyright,
.p1-footer[data-tone="accent"] .p1-footer__legal-item { color: var(--p1-fg-inverse-muted); }
.p1-footer[data-tone="light"] .p1-footer__copyright,
.p1-footer[data-tone="light"] .p1-footer__legal-item { color: var(--p1-fg-muted); }

.p1-footer__legal-links { display: flex; flex-wrap: wrap; gap: 1.25rem; }

.p1-footer__legal-spacer { flex: 1; }

/* Social icons */
.p1-footer__social { display: flex; gap: 0.75rem; }

.p1-footer__social-btn {
  align-items: center;
  block-size: 2.25rem;
  border-radius: var(--p1-radius-pill);
  border: 1px solid;
  display: grid;
  inline-size: 2.25rem;
  place-items: center;
}
.p1-footer[data-tone="dark"] .p1-footer__social-btn {
  border-color: var(--p1-border-inverse);
  color: var(--p1-fg-inverse-muted);
}
.p1-footer[data-tone="accent"] .p1-footer__social-btn {
  border-color: var(--p1-border-inverse);
  color: var(--p1-fg-inverse-muted);
}
.p1-footer[data-tone="light"] .p1-footer__social-btn {
  border-color: var(--p1-border);
  color: var(--p1-fg-muted);
}

.p1-footer__social-icon { block-size: 1rem; inline-size: 1rem; }

.p1-footer__social-standalone {
  display: flex;
  justify-content: end;
  margin-block-start: var(--p1-space-lg);
}

